import csv
with open('csv/races.csv') as f:
    races = {row[0]: row for row in csv.reader(f)}
with open('csv/driverStandings.csv') as f:
    ds = list(csv.reader(f))
yoong_races = set()
for row in ds:
    if row[2] == '62':
        yoong_races.add(row[1])
result = set()
for raceId in yoong_races:
    if raceId in races:
        r = races[raceId]
        if int(r[2]) < 20:
            result.add(r[4])
print(sorted(result))

